<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
declare global { interface Window { pywebview?: { api?: { open_external:(url:string)=>Promise<boolean>;open_notice_window:(url:string)=>Promise<boolean> } } } }
type Step={id:string;title:string;detail:string;due_date:string;status:string;order:number;depends_on:string[]}
type Analysis={material_done?:string[];summary?:string;category?:string;priority?:string;risks?:string[];links?:{label:string;url:string}[];contacts?:{label:string;value:string}[]}
type Notice={content_version:string;notice_links:{label:string;url:string;attachment?:boolean}[];analysis:Analysis;tasks:Step[];content:string;id:string;title:string;url:string;relevance_reason:string;relevant:number|null;deadline:string|null;materials:string[];task_status:string;notes:string}
type Source={id:string;url:string;label:string;last_sync:string|null;last_error:string}
type Profile={name:string;school:string;major:string;keywords:string}
const page=ref('notices'),notices=ref<Notice[]>([]),sources=ref<Source[]>([]),selected=ref<Notice|null>(null),search=ref(''),busy=ref(false),toast=ref(''),sourceUrl=ref(''),sourceLabel=ref(''),profile=ref<Profile>({name:'',school:'',major:'',keywords:''}),provider=ref('none'),apiKey=ref(''),model=ref('gpt-6-luna'),openaiModel=ref('gpt-6-luna'),deepseekModel=ref('deepseek-chat'),models=ref<string[]>([]),readingModels=ref(false)
const bodyLoading=ref(false),bodyError=ref('')
async function readBody(force=false){if(!selected.value||bodyLoading.value)return;if(!force&&Number(selected.value.content_version)>=2)return;bodyLoading.value=true;bodyError.value='';const id=selected.value.id;try{const n=await api<Notice>('/notices/'+id+'/body',{method:'POST'});const i=notices.value.findIndex(x=>x.id===id);if(i>=0)notices.value[i]=n;if(selected.value?.id===id)selected.value=n}catch(e){bodyError.value=e instanceof Error?e.message:'通知正文读取失败'}finally{bodyLoading.value=false}}
const webNoticeId=ref(''),webRevision=ref(0)
function expandBody(e:Event){if((e.target as HTMLDetailsElement).open&&selected.value)webNoticeId.value=selected.value.id;else webNoticeId.value=''}
async function reloadWebpage(){await readBody(true);webRevision.value++}
async function openFullWebpage(url:string){if(window.pywebview?.api?.open_notice_window){await window.pywebview.api.open_notice_window(url)}else await openNotice(url)}
const relevanceFilter=ref('all'),categoryFilter=ref('all'),batchProgress=ref('')
const shown=computed(()=>notices.value.filter(x=>(relevanceFilter.value==='all'||(relevanceFilter.value==='related'?x.relevant===1:x.relevant===null))&&(categoryFilter.value==='all'||x.analysis?.category===categoryFilter.value)&&(x.title+' '+x.relevance_reason).toLowerCase().includes(search.value.toLowerCase())))
const categories:Record<string,string>={exam:'考试',scholarship:'奖助学金',teaching:'教学',activity:'活动',competition:'竞赛',administration:'事务办理',other:'其他'}
const priorities:Record<string,string>={urgent:'紧急',high:'高优先级',normal:'普通',low:'低优先级'}
const activeTasks=computed(()=>notices.value.filter(n=>['todo','doing','done'].includes(n.task_status)))
function progress(n:Notice){return (n.tasks||[]).filter(x=>x.status==='done').length+' / '+(n.tasks||[]).length}
function due(n:Notice){if(!n.deadline)return '未确认截止日期';const days=Math.ceil((new Date(n.deadline+'T00:00:00').getTime()-new Date(new Date().toDateString()).getTime())/86400000);return days<0?'已逾期 '+Math.abs(days)+' 天':days===0?'今天截止':'剩余 '+days+' 天'}
const names:Record<string,string>={new:'新发现',todo:'待办理',doing:'办理中',done:'已完成',ignored:'已忽略'}
async function openNotice(url:string){if(window.pywebview?.api?.open_external){await window.pywebview.api.open_external(url);return}window.open(url,'_blank','noopener,noreferrer')}
async function api<T>(p:string,o:RequestInit={}):Promise<T>{const r=await fetch('/api'+p,{...o,headers:{'Content-Type':'application/json',...(o.headers||{})}});const raw=await r.text();let data:any;try{data=raw?JSON.parse(raw):null}catch{throw new Error(raw||'服务器返回了无效响应')}if(!r.ok)throw new Error(data?.detail||'操作失败');return data as T}
function msg(x:string){toast.value=x;setTimeout(()=>toast.value='',5000)}
async function load(){[notices.value,sources.value]=await Promise.all([api<Notice[]>('/notices'),api<Source[]>('/sources')]);profile.value=await api<Profile>('/profile');const s=await api<any>('/settings');provider.value=s.provider;openaiModel.value=s.openai_model;deepseekModel.value=s.deepseek_model;model.value=provider.value==='deepseek'?deepseekModel.value:openaiModel.value;notices.value.forEach(n=>{n.analysis=n.analysis||{};n.tasks=n.tasks||[]});selected.value=notices.value.find(n=>n.id===selected.value?.id)||notices.value[0]||null}
async function scan(){busy.value=true;try{const r=await api<{results:{new:number}[]}>('/sources/scan',{method:'POST'});await load();msg('扫描完成，发现 '+r.results.reduce((a,x)=>a+x.new,0)+' 条新通知')}catch(e){msg(e instanceof Error?e.message:'扫描失败')}finally{busy.value=false}}
async function addSource(){try{await api('/sources',{method:'POST',body:JSON.stringify({url:sourceUrl.value,label:sourceLabel.value})});sourceUrl.value='';sourceLabel.value='';sources.value=await api<Source[]>('/sources');msg('来源已添加')}catch(e){msg(e instanceof Error?e.message:'添加失败')}}
async function deleteSource(s:Source){if(!confirm('确定删除这个通知来源吗？'))return;try{await api('/sources/'+s.id,{method:'DELETE'});sources.value=sources.value.filter(x=>x.id!==s.id);msg('来源已删除')}catch(e){msg(e instanceof Error?e.message:'删除失败')}}
async function analyzePending(){const pending=shown.value.filter(n=>n.relevant===null);if(!pending.length){msg('当前范围没有待分析通知');return}busy.value=true;let done=0;const failures:string[]=[];try{for(const n of pending){batchProgress.value='正在分析 '+(done+failures.length+1)+' / '+pending.length;try{const result=await api<Notice>('/notices/'+n.id+'/analyze',{method:'POST'});const i=notices.value.findIndex(x=>x.id===n.id);if(i>=0)notices.value[i]=result;if(selected.value?.id===n.id)selected.value=result;done++}catch(e){failures.push(String(e));}}msg('完成 '+done+' 条'+(failures.length?'，失败 '+failures.length+' 条：'+failures[0]:''))}finally{busy.value=false;batchProgress.value=''}}
async function analyze(){if(!selected.value)return;busy.value=true;try{accept(await api<Notice>('/notices/'+selected.value.id+'/analyze',{method:'POST'}));msg('办理计划已生成，请确认后加入待办')}catch(e){msg(e instanceof Error?e.message:'分析失败')}finally{busy.value=false}}
async function task(status:string){if(!selected.value)return;selected.value=await api<Notice>('/notices/'+selected.value.id+'/task',{method:'PUT',body:JSON.stringify({status,notes:selected.value.notes})});notices.value=await api<Notice[]>('/notices')}
async function saveProfile(){profile.value=await api<Profile>('/profile',{method:'PUT',body:JSON.stringify(profile.value)});msg('档案已保存')}
function switchProvider(next:string){if(provider.value==='openai')openaiModel.value=model.value;if(provider.value==='deepseek')deepseekModel.value=model.value;provider.value=next;models.value=[];model.value=next==='openai'?openaiModel.value:next==='deepseek'?deepseekModel.value:'';apiKey.value=''}
async function readModels(){if(provider.value==='none')return;readingModels.value=true;try{const r=await api<{models:string[]}>('/models',{method:'POST',body:JSON.stringify({provider:provider.value,api_key:apiKey.value||null})});models.value=r.models;if(!r.models.includes(model.value))model.value=r.models[0]||model.value;msg('已读取 '+r.models.length+' 个模型')}catch(e){msg(e instanceof Error?e.message:'读取模型失败')}finally{readingModels.value=false}}
async function saveSettings(){if(provider.value==='openai')openaiModel.value=model.value;if(provider.value==='deepseek')deepseekModel.value=model.value;await api('/settings',{method:'PUT',body:JSON.stringify({provider:provider.value,openai_model:openaiModel.value,deepseek_model:deepseekModel.value,openai_key:provider.value==='openai'?(apiKey.value||null):null,deepseek_key:provider.value==='deepseek'?(apiKey.value||null):null})});apiKey.value='';msg('模型设置已保存')}

function accept(n:Notice){selected.value=n;const i=notices.value.findIndex(x=>x.id===n.id);if(i>=0)notices.value[i]=n}
async function savePlan(){if(!selected.value)return;try{accept(await api<Notice>('/notices/'+selected.value.id+'/analysis',{method:'PUT',body:JSON.stringify({summary:selected.value.analysis.summary,category:selected.value.analysis.category,priority:selected.value.analysis.priority,deadline:selected.value.deadline||'',materials:selected.value.materials,material_done:selected.value.analysis.material_done||[],action_items:selected.value.tasks})}));msg('办理计划已保存')}catch(e){msg(String(e))}}
async function toggleMaterial(m:string){if(!selected.value)return;const a=selected.value.analysis.material_done||[];selected.value.analysis.material_done=a.includes(m)?a.filter(x=>x!==m):[...a,m];await savePlan()}
async function toggleStep(t:Step){t.status=t.status==='done'?'todo':'done';await savePlan()}
function moveStep(index:number,delta:number){if(!selected.value)return;const a=selected.value.tasks;const j=index+delta;if(j<0||j>=a.length)return;[a[index],a[j]]=[a[j],a[index]];a.forEach((x,i)=>x.order=i+1)}
function addStep(){selected.value?.tasks.push({id:crypto.randomUUID(),title:'新步骤',detail:'',due_date:'',status:'todo',order:selected.value.tasks.length+1,depends_on:[]})}
async function copyPlan(){if(!selected.value)return;const n=selected.value;const text=[n.title,n.analysis.summary||n.relevance_reason,'截止：'+(n.deadline||'待确认'),'材料：'+n.materials.join('、'),...n.tasks.map((x,i)=>(i+1)+'. '+x.title+' '+x.detail),n.url].join('\n');try{await navigator.clipboard.writeText(text);msg('办理计划已复制')}catch{msg('无法访问剪贴板，请选择文字复制')}}
function exportCalendar(){if(!selected.value?.deadline){msg('请先确认截止日期');return}const n=selected.value;const esc=(v:string)=>v.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,m=>'\\'+m);const next=new Date(n.deadline+'T12:00:00');next.setDate(next.getDate()+1);const end=next.getFullYear()+String(next.getMonth()+1).padStart(2,'0')+String(next.getDate()).padStart(2,'0');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//CampusRadar//CN','BEGIN:VEVENT','UID:'+n.id+'@campusradar','DTSTAMP:'+stamp,'DTSTART;VALUE=DATE:'+n.deadline.replace(/-/g,''),'DTEND;VALUE=DATE:'+end,'SUMMARY:'+esc(n.title),'DESCRIPTION:'+esc((n.analysis.summary||n.relevance_reason)+'\n'+n.url),'BEGIN:VALARM','TRIGGER:-P1D','ACTION:DISPLAY','DESCRIPTION:校园事项即将截止','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([data],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='校园事项.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>load().catch(e=>msg(String(e))))

type RagSource={id:string;notice_id:string;title:string;url:string;excerpt:string}
type RagResult={claims:{text:string;citations:{id:string;quote:string}[]}[];sources:RagSource[];missing:string;grounded:boolean}
const question=ref(''),ragScope=ref(''),ragBusy=ref(false),ragError=ref(''),ragResult=ref<RagResult|null>(null),ragQuestion=ref(''),ragStats=ref({documents:0,chunks:0,pending:0}),indexProgress=ref('')
async function ragStatus(){try{ragStats.value=await api<typeof ragStats.value>('/rag/index')}catch(e){ragError.value=String(e)}}
async function openRag(){page.value='rag';await ragStatus()}
async function prepareRag(){ragBusy.value=true;ragError.value='';let failed=0;try{const all=await api<Notice[]>('/notices');const pending=all.filter(n=>Number(n.content_version)<2||!n.content?.trim());for(let i=0;i<pending.length;i++){indexProgress.value='读取正文 '+(i+1)+' / '+pending.length;try{await api('/notices/'+pending[i].id+'/body',{method:'POST'})}catch{failed++}}await ragStatus();if(failed)ragError.value=failed+' 条通知正文读取失败，其余通知已入库。';msg('资料更新完成')}catch(e){ragError.value=e instanceof Error?e.message:String(e)}finally{ragBusy.value=false;indexProgress.value=''}}
async function askRag(){if(question.value.trim().length<2||ragBusy.value)return;ragBusy.value=true;ragError.value='';ragResult.value=null;ragQuestion.value=question.value.trim();try{ragResult.value=await api<RagResult>('/rag/ask',{method:'POST',body:JSON.stringify({question:ragQuestion.value,source_id:ragScope.value})});await ragStatus()}catch(e){ragError.value=e instanceof Error?e.message:String(e)}finally{ragBusy.value=false}}
async function showRagNotice(id:string){try{const n=await api<Notice>('/notices/'+id);selected.value=n;page.value='notices'}catch(e){msg(String(e))}}
async function copyRag(){if(!ragResult.value)return;const r=ragResult.value;try{await navigator.clipboard.writeText([ragQuestion.value,...r.claims.map(c=>c.text+' '+c.citations.map(x=>'['+x.id+']').join('')),r.missing,...r.sources.map(x=>'['+x.id+'] '+x.title+' '+x.url)].join('\n\n'));msg('回答和出处已复制')}catch{msg('复制失败，可直接选中文字复制')}}

</script>
<template><div class="app-shell"><aside class="sidebar"><button class="nav-item" :class="{active:page==='notices'}" @click="page='notices'">通知雷达 <b>{{notices.length}}</b></button><button class="nav-item" :class="{active:page==='tasks'}" @click="page='tasks'">我的待办</button><button class="nav-item" :class="{active:page==='rag'}" @click="openRag">通知问答</button><button class="nav-item" :class="{active:page==='profile'}" @click="page='profile'">学生档案</button><div class="sidebar-bottom"><button class="nav-item" :class="{active:page==='settings'}" @click="page='settings'">来源与设置</button></div></aside><main class="main-area">
<template v-if="page==='notices'"><header class="page-head"><div><h1>通知雷达</h1><p>从校园通知中找出与你有关的事项，并追踪截止日期。</p></div><div class="head-actions"><button class="secondary" @click="load">刷新</button><button class="secondary" :disabled="busy||!notices.length" @click="analyzePending">{{batchProgress||'分析待判断通知'}}</button><button class="primary" :disabled="busy||!sources.length" @click="scan">扫描通知</button></div></header><div v-if="!sources.length" class="panel onboarding"><strong>先添加校园通知来源</strong><p>在“来源与设置”中粘贴学校或学院通知页面。</p><button class="primary" @click="page='settings'">添加来源</button></div><div class="work-layout"><div class="panel job-list"><div class="list-toolbar"><input v-model="search" class="input" placeholder="搜索通知"><div class="form-two"><select class="input" v-model="relevanceFilter"><option value="all">全部通知</option><option value="related">与我相关</option><option value="pending">待判断</option></select><select class="input" v-model="categoryFilter"><option value="all">全部分类</option><option v-for="(v,k) in categories" :key="k" :value="k">{{v}}</option></select></div><span>{{shown.length}} 条</span></div><div class="job-scroll"><button v-for="n in shown" :key="n.id" class="job-row" :class="{selected:selected?.id===n.id}" @click="selected=n"><strong>{{n.title}}</strong><small>{{n.deadline?'截止 '+n.deadline:'未识别截止日期'}} · {{names[n.task_status]}}</small></button><div v-if="!shown.length" class="empty">还没有通知。</div></div></div><div v-if="selected" class="panel job-detail"><div class="detail-top"><span class="pill">{{selected.relevant===1?'与你相关':selected.relevant===0?'与你无关':'待判断'}}</span><small>{{names[selected.task_status]}}</small></div><h2>{{selected.title}}</h2><p class="muted">{{selected.deadline?'截止日期：'+selected.deadline:'未识别截止日期'}}</p><div class="detail-actions"><button class="primary" @click="openNotice(selected.url)">打开原通知</button><button class="secondary" :disabled="busy" @click="analyze">{{busy?'正在生成计划…':'生成办理计划'}}</button></div><section class="detail-section analysis"><div class="section-heading"><h3>办理计划</h3><span class="pill">{{priorities[selected.analysis.priority||'normal']}}</span></div><p>{{selected.analysis.summary||selected.relevance_reason||'点击 Agent 分析，读取正文并生成办理计划。'}}</p><small v-if="selected.relevance_reason" class="muted">判断依据：{{selected.relevance_reason}}</small><div class="detail-actions"><button class="primary" @click="task('todo')">加入我的待办</button><button class="secondary" @click="copyPlan">复制计划</button><button class="secondary" @click="exportCalendar">导出日历提醒</button></div><div class="form-two"><label>分类<select class="input" v-model="selected.analysis.category"><option v-for="(v,k) in categories" :value="k" :key="k">{{v}}</option></select></label><label>优先级<select class="input" v-model="selected.analysis.priority"><option v-for="(v,k) in priorities" :value="k" :key="k">{{v}}</option></select></label></div><label>截止日期<input class="input" type="date" v-model="selected.deadline"></label><p class="deadline-banner">{{due(selected)}}</p><label>结论<textarea class="textarea short" v-model="selected.analysis.summary"></textarea></label>
<details open class="plan-section"><summary>办理步骤 · {{progress(selected)}}</summary><div v-for="(t,i) in selected.tasks" :key="t.id" class="step-card"><div class="step-heading"><input type="checkbox" :checked="t.status==='done'" @change="toggleStep(t)"><span>{{i+1}}</span><input class="input" v-model="t.title" :class="{completed:t.status==='done'}"><button class="secondary mini" :disabled="i===0" @click="moveStep(i,-1)">↑</button><button class="secondary mini" :disabled="i===selected.tasks.length-1" @click="moveStep(i,1)">↓</button><button class="danger mini" @click="selected.tasks.splice(i,1)">删除</button></div><textarea class="textarea short" v-model="t.detail" placeholder="步骤说明"></textarea><div class="form-two"><input class="input" type="date" v-model="t.due_date"><select class="input" v-model="t.status"><option value="todo">待办理</option><option value="doing">办理中</option><option value="done">已完成</option><option value="new">待确认</option></select></div></div><p v-if="!selected.tasks.length" class="muted">没有明确步骤，可手工添加；请勿把栏目介绍当成办理通知。</p><button class="secondary mini" @click="addStep">添加步骤</button></details>
<details open class="plan-section"><summary>材料清单 · {{selected.materials.length}} 项</summary><div v-for="(m,i) in selected.materials" :key="i" class="material-edit"><input type="checkbox" :checked="selected.analysis.material_done?.includes(m)" @change="toggleMaterial(m)"><input class="input" v-model="selected.materials[i]"><button class="danger mini" @click="selected.materials.splice(i,1)">删除</button></div><button class="secondary mini" @click="selected.materials.push('新材料')">添加材料</button></details>
<details v-if="selected.analysis.risks?.length" open class="plan-section"><summary>需要注意</summary><ul><li v-for="r in selected.analysis.risks" :key="r">{{r}}</li></ul></details><details v-if="selected.notice_links?.length" class="plan-section"><summary>附件与正文链接 · {{selected.notice_links.length}} 项</summary><div class="notice-link-grid"><button v-for="l in selected.notice_links" :key="l.url" class="notice-link" @click="openNotice(l.url)"><span class="link-kind">{{l.attachment?'附件':'正文链接'}}</span><span>{{l.label}}</span><span aria-hidden="true">↗</span></button></div></details><p v-for="c in selected.analysis.contacts" :key="c.value">{{c.label}}：{{c.value}}</p><button class="primary" @click="savePlan">保存计划修改</button></section><details :key="selected.id" class="detail-section notice-body" @toggle="expandBody"><summary>查看通知网页</summary><div class="body-toolbar"><span class="muted">保留原通知的表格、图片和段落排版</span><div class="webpage-actions"><button class="secondary mini" :disabled="bodyLoading" @click="reloadWebpage">{{bodyLoading?'读取中…':'刷新网页'}}</button><button class="secondary mini" @click="openFullWebpage(selected.url)">打开完整网页</button></div></div><p v-if="bodyError" class="danger-text">{{bodyError}}</p><iframe v-if="webNoticeId===selected.id" :key="selected.id+'-'+webRevision" :src="'/api/notices/'+selected.id+'/webpage?v='+webRevision" class="notice-webframe" title="通知网页正文" sandbox="allow-popups allow-popups-to-escape-sandbox allow-downloads" referrerpolicy="no-referrer"></iframe></details><section class="detail-section"><h3>办理状态</h3><select v-model="selected.task_status" class="input" @change="task(selected.task_status)"><option v-for="(v,k) in names" :key="k" :value="k">{{v}}</option></select><textarea v-model="selected.notes" class="textarea short"></textarea><button class="secondary" @click="task(selected.task_status)">保存状态</button></section></div></div></template>
<template v-else-if="page==='tasks'"><header class="page-head"><div><h1>我的待办</h1><p>只显示已加入待办的事项，跟踪下一步和截止日期。</p></div></header><div class="progress-grid"><div v-for="state in ['todo','doing','done']" :key="state" class="panel progress-column"><div class="column-head"><strong>{{names[state]}}</strong></div><button v-for="n in activeTasks.filter(x=>x.task_status===state)" :key="n.id" class="progress-card" @click="page='notices';selected=n"><strong>{{n.title}}</strong><small>{{due(n)}} · 已完成 {{progress(n)}} 步</small><small>{{(n.tasks||[]).find(t=>t.status!=='done')?.title||'暂无未完成步骤'}}</small></button></div></div></template>
<template v-else-if="page==='rag'"><header class="page-head"><div><h1>通知问答</h1><p>从已收录通知中查找原文，回答问题并展示出处。</p></div><button class="secondary" :disabled="ragBusy" @click="prepareRag">{{indexProgress||'更新问答资料'}}</button></header>
<section class="panel rag-form"><div class="rag-stats">已入库 {{ragStats.documents}} 条通知 · {{ragStats.chunks}} 个原文片段<span v-if="ragStats.pending"> · {{ragStats.pending}} 条正文待读取</span></div><p v-if="ragStats.pending" class="muted">首次使用请点击“更新问答资料”，读取尚未入库的正文。</p><label>检索范围<select class="input" v-model="ragScope" :disabled="ragBusy"><option value="">全部通知来源</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.label}}</option></select></label><label>你的问题<textarea class="textarea short" v-model="question" maxlength="500" placeholder="例如：微专业报名需要准备哪些材料？" :disabled="ragBusy" @keydown.ctrl.enter.prevent="askRag"></textarea></label><div class="detail-actions"><button class="primary" :disabled="ragBusy||question.trim().length<2" @click="askRag">{{ragBusy?'处理中…':'查资料并回答'}}</button><span class="muted">Ctrl + Enter 提问</span></div><p v-if="ragError" class="danger-text" role="alert">{{ragError}}</p></section>
<section v-if="ragResult" class="panel rag-answer" aria-live="polite"><div class="section-heading"><h2>{{ragResult.grounded?'基于通知原文的回答':'资料不足'}}</h2><button class="secondary mini" @click="copyRag">复制回答与出处</button></div><p class="muted">{{ragQuestion}}</p><div v-for="(claim,i) in ragResult.claims" :key="i" class="rag-claim"><p>{{claim.text}}</p><details><summary>查看引用原文 · {{claim.citations.map(c=>c.id).join('、')}}</summary><blockquote v-for="(c,j) in claim.citations" :key="j"><strong>[{{c.id}}]</strong> {{c.quote}}</blockquote></details></div><p v-if="ragResult.missing" class="rag-missing">{{ragResult.missing}}</p><p class="muted">请核对原通知适用对象与发布日期，历史通知不代表现行政策。</p><h3 v-if="ragResult.sources.length">检索到的资料</h3><details v-for="s in ragResult.sources" :key="s.id" class="rag-source"><summary>[{{s.id}}] {{s.title}}</summary><p class="rag-excerpt">{{s.excerpt}}</p><div class="detail-actions"><button class="secondary mini" @click="showRagNotice(s.notice_id)">查看通知</button><button class="secondary mini" @click="openNotice(s.url)">打开原网页</button></div></details></section></template>
<template v-else-if="page==='profile'"><header class="page-head"><div><h1>学生档案</h1><p>Agent 会根据档案判断通知是否与你有关。</p></div></header><div class="panel profile-form"><label>称呼<input v-model="profile.name" class="input"></label><label>学校<input v-model="profile.school" class="input"></label><label>专业和年级<input v-model="profile.major" class="input"></label><label>关注方向<textarea v-model="profile.keywords" class="textarea"></textarea></label><button class="primary" @click="saveProfile">保存档案</button></div></template>
<template v-else><header class="page-head"><div><h1>来源与设置</h1><p>添加学校通知页，并选择分析模型。</p></div></header><div class="panel settings-card"><h2>通知来源</h2><label>通知页面链接<input v-model="sourceUrl" class="input" placeholder="https://www.example.edu.cn/notice"></label><label>显示名称<input v-model="sourceLabel" class="input" placeholder="教务处通知"></label><button class="primary" :disabled="!sourceUrl" @click="addSource">添加来源</button><div class="source-list"><div v-for="s in sources" :key="s.id" class="source-row"><div><strong>{{s.label}}</strong><small>{{s.url}}</small></div><button class="danger" @click="deleteSource(s)">删除</button></div></div></div><div class="panel settings-card"><h2>模型服务</h2><div class="provider-tabs"><button v-for="x in [{id:'none',name:'仅抓取'},{id:'openai',name:'OpenAI'},{id:'deepseek',name:'DeepSeek'}]" :key="x.id" :class="{active:provider===x.id}" @click="switchProvider(x.id)">{{x.name}}</button></div><input v-if="provider!=='none'" v-model="apiKey" class="input" type="password" placeholder="API Key"><div v-if="provider!=='none'" class="model-tools"><select v-if="models.length" v-model="model" class="input"><option v-for="m in models" :key="m" :value="m">{{m}}</option></select><input v-else v-model="model" class="input" placeholder="模型名称"><button class="secondary" :disabled="readingModels" @click="readModels">{{readingModels?'读取中…':'读取模型'}}</button></div><button class="primary" @click="saveSettings">保存设置</button></div></template>
</main><div v-if="toast" class="toast">{{toast}}</div></div></template>
